#!/usr/bin/env node
/**
 * The CRM must never present its 54 fabricated placeholder leads as real data.
 *
 * WHAT HAPPENED. Marco opened the CRM, saw 54 leads, and reported that his data
 * was missing. It was worse than missing: those 54 rows are GENERATED by the
 * page itself — invented names, invented activity, invented statuses — and they
 * had replaced nothing, because `loadLive()` hit `if (rawLeads.length < 3)
 * return;  // too sparse - keep the demo set` and quietly gave up. The only
 * signal was a small corner chip reading "Demo data · swaps to live clients on
 * finalize", which reads as a pending launch step rather than "your real data
 * did not load".
 *
 * So a real estate agent was looking at a board of people who do not exist and
 * had no way to know. That is the single most dangerous state this app can be
 * in, and it is what this suite exists to make impossible.
 *
 * Usage: PW_CHROMIUM=... node scripts/verify-no-fake-leads.mjs
 */
import { spawn } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { chromium } from "playwright";

const PORT = 3995;
const B = `http://127.0.0.1:${PORT}`;
const tmp = mkdtempSync(join(tmpdir(), "nofake-"));
let pass = 0; const fail = [];
const ok = (n, c, d) => { if (c) { pass++; console.log("  ok " + n); } else { fail.push(n + (d ? " — " + d : "")); console.error("FAIL " + n + (d ? " — " + d : "")); } };

/* An EMPTY store — the exact condition that used to leave 54 invented people on
   screen looking like a working CRM. */
writeFileSync(join(tmp, "db.json"), JSON.stringify({
  idCounter: 1, leadsById: {}, leadKeyToId: {}, conversationsByLeadId: {}, commandTasks: [],
}));

const env = { ...process.env, PORT: String(PORT), SITE_LOGIN_ENABLED: "0",
  DB_JSON_PATH: join(tmp, "db.json"), TASKS_JSON_PATH: join(tmp, "tasks.json"),
  DATA_DIR: tmp, AUTH_DB_PATH: join(tmp, "auth.db") };
delete env.BRIVITY_API_KEY;

const srv = spawn(process.execPath, [join(process.cwd(), "dist/src/server.js")], {
  cwd: process.cwd(), env, stdio: ["ignore", "pipe", "pipe"] });
process.on("exit", () => { try { srv.kill("SIGKILL"); } catch {} });
const until = async (fn, ms = 30000) => { const t0 = Date.now(); for (;;) { try { if (await fn()) return; } catch {} if (Date.now() - t0 > ms) throw new Error("timeout"); await new Promise((r) => setTimeout(r, 300)); } };
await until(async () => (await fetch(B + "/health")).ok);

const browser = await chromium.launch({ executablePath: process.env.PW_CHROMIUM });
try {
  const page = await browser.newPage();
  const errs = []; page.on("pageerror", (e) => errs.push(String(e)));
  await page.goto(B + "/crm", { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);

  const live = await page.evaluate(() => (typeof LIVE_DATA !== "undefined" ? LIVE_DATA : null));
  const count = await page.evaluate(() => (typeof LEADS !== "undefined" ? LEADS.length : -1));
  ok("with an empty store the board is NOT live data", live === false, String(live));
  ok("and it is the 54 placeholder rows that are showing", count === 54, String(count));

  await page.locator('[data-view="leads"]').click();
  await page.waitForTimeout(400);
  if (process.env.SHOT) await page.screenshot({ path: process.env.SHOT });
  const banner = await page.locator("#brvBanner").innerText();
  ok("the page states outright that these are not real leads",
    /not your data|sample leads/i.test(banner), banner.slice(0, 160));
  ok("it says the rows are placeholders and none are real",
    /placeholder/i.test(banner) && /none of them are real/i.test(banner), banner.slice(0, 220));
  ok("it explains WHY live data did not load",
    /did not load/i.test(banner), banner.slice(0, 220));
  ok("it warns against acting on them",
    /should be called, texted or acted on|not be called/i.test(banner), banner.slice(0, 260));

  /* Not dismissible: the whole failure was someone believing these rows. */
  ok("there is no dismiss button on the sample-data warning",
    (await page.locator("#brvBannerX").count()) === 0);

  /* The corner chip must not imply this is a normal pre-launch state. */
  const tag = await page.locator("#demoTag").innerText();
  ok("the corner chip says sample data, not 'swaps to live on finalize'",
    /sample data/i.test(tag) && !/finalize/i.test(tag), tag);

  ok("no page errors", errs.length === 0, errs.join("; "));

  /* ---- and the inverse: real data must NOT be labelled fake -------------- */
  const leads = {}; const convos = {};
  for (let i = 0; i < 5; i++) {
    const id = "real_" + i;
    leads[id] = { id, platform: "instagram", userId: "u" + i, username: "@u" + i,
      name: "Real Person " + i, phone: null, email: null, state: "new",
      source: "Instagram", createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() };
    convos[id] = { messages: [{ role: "user", text: "hi", at: new Date().toISOString() }] };
  }
  writeFileSync(join(tmp, "db.json"), JSON.stringify({
    idCounter: 50, leadsById: leads,
    leadKeyToId: Object.fromEntries(Object.values(leads).map((l) => [l.platform + "::" + l.userId, l.id])),
    conversationsByLeadId: convos, commandTasks: [] }));
  srv.kill("SIGKILL");
  const srv2 = spawn(process.execPath, [join(process.cwd(), "dist/src/server.js")], {
    cwd: process.cwd(), env, stdio: ["ignore", "pipe", "pipe"] });
  process.on("exit", () => { try { srv2.kill("SIGKILL"); } catch {} });
  await until(async () => (await fetch(B + "/health")).ok);

  const p2 = await browser.newPage();
  await p2.goto(B + "/crm", { waitUntil: "networkidle" });
  await p2.waitForTimeout(1500);
  const live2 = await p2.evaluate(() => (typeof LIVE_DATA !== "undefined" ? LIVE_DATA : null));
  const count2 = await p2.evaluate(() => (typeof LEADS !== "undefined" ? LEADS.length : -1));
  ok("five real phoneless leads DO replace the placeholders", live2 === true, String(live2));
  ok("and the board shows exactly them, not 54", count2 === 5, String(count2));
  await p2.locator('[data-view="leads"]').click();
  await p2.waitForTimeout(400);
  const banner2 = await p2.locator("#brvBanner").innerText().catch(() => "");
  ok("real data is never labelled as sample data",
    !/not your data|placeholder/i.test(banner2), banner2.slice(0, 140));
  const tag2 = await p2.locator("#demoTag").innerText();
  ok("and the chip flips to live", /live data/i.test(tag2), tag2);

  /* ---- a SLOW Brivity must not hold the board on fabricated data ---------
     The real account takes 25-30s to return ~2,900 contacts. That call used to
     be awaited alongside the lead snapshot, so for that whole window every page
     load displayed the 54 invented leads. This simulates the slow call and
     asserts the board is real long before it finishes. */
  const p3 = await browser.newPage();
  await p3.route("**/api/brivity/people*", async (route) => {
    await new Promise((r) => setTimeout(r, 6000));      // stand-in for ~26s
    await route.fulfill({ status: 200, contentType: "application/json",
      body: JSON.stringify({ ok: true, configured: true, count: 0, people: [] }) });
  });
  const t0 = Date.now();
  await p3.goto(B + "/crm", { waitUntil: "domcontentloaded" });
  await p3.waitForFunction(() => typeof LIVE_DATA !== "undefined" && LIVE_DATA === true, null, { timeout: 5500 });
  const elapsed = Date.now() - t0;
  ok("the board goes live without waiting for the slow Brivity call",
    elapsed < 5500, elapsed + "ms");
  const c3 = await p3.evaluate(() => LEADS.length);
  ok("and it is showing the real leads, not the 54 placeholders", c3 === 5, String(c3));
  console.log("  (live in " + elapsed + "ms against a 6s Brivity stub)");
  await p3.close();

  srv2.kill("SIGKILL");
} finally { await browser.close(); }

console.log(`\n${pass} passed, ${fail.length} failed`);
if (fail.length) { console.error(fail.map((f) => " - " + f).join("\n")); process.exit(1); }
